import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { createHash } from "node:crypto";
import { ControlCommand, withControlledSumatra, type ControlClient } from "../tests/control.ts";
import { assemblePdf, EXE, makePng, makeZip, SETTINGS_FILE } from "../tests/util.ts";
import { postMessage, waitForTopWindow, WM_CLOSE } from "../tests/winapi.ts";

const root = resolve(`out/full-review-contracts-data-${process.env.REVIEW_RUN ?? "2"}`);
mkdirSync(root, { recursive: true });
const results: unknown[] = [];
function record(result: unknown) {
  results.push(result);
  writeFileSync(join(root, "results.json"), JSON.stringify(results, null, 2));
  console.log(JSON.stringify(result));
}
function check(ok: unknown, why: string): asserts ok {
  if (!ok) throw new Error(why);
}
function settings(dir: string) {
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, SETTINGS_FILE), "UiLanguage = en\nRestoreSession = false\nCheckForUpdates = false\nReloadModifiedDocuments = false\nDisableJavaScript = false\n");
}
async function query(client: ControlClient, args: (string | number)[]) {
  return client.request(ControlCommand.TestCurrentPdf, args);
}
async function form(type: "text" | "choice", engine: string, round: number) {
  const dir = join(root, `${type}-${engine}-${round}`);
  settings(dir);
  const path = join(dir, "form.pdf");
  const field = type === "text" ? "/FT /Tx" : "/FT /Ch /Ff 131072 /Opt [(first) (second)]";
  writeFileSync(path, assemblePdf([
    "<< /Type /Catalog /Pages 2 0 R /AcroForm << /Fields [4 0 R] /DR << /Font << /Helv 5 0 R >> >> >> >>",
    "<< /Type /Pages /Count 1 /Kids [3 0 R] >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 600 700] /Annots [4 0 R] >>",
    `<< /Type /Annot /Subtype /Widget ${field} /T (field) /V (first) /Rect [100 300 500 400] /P 3 0 R /F 4 /DA (/Helv 18 Tf 0 g) /AA << /V << /S /JavaScript /JS (event.rc = false;) >> >> >>`,
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
  ]), "latin1");
  await withControlledSumatra(EXE, async (client, proc) => {
    await client.waitForRenderIdle();
    const before = await query(client, ["editor"]);
    const edit = await client.setFormField(1, 0, "second");
    const after = await client.request(ControlCommand.TestMarkupAnnots);
    check(String(edit[1]).includes("before='first' after='first'"), `validation did not reject: ${edit}`);
    check(edit[0] === (type === "text" ? 1 : 0), `unexpected setter result: ${edit}`);
    check(String(after[1]).includes(`modified=${type === "text" ? 0 : 1}`), `unexpected dirty: ${after}`);
    record({ kind: "validation-rejection", engine, type, round, before, edit, after: /undo .*\n/.exec(String(after[1]))?.[0].trim() });
  }, ["-appdata", dir, "-log-to-file", join(dir, "app.log"), path], { env: { ...process.env, SOLOKPDF_ENGINE: engine } });
}
function epub(word: string) {
  const entries = {
    mimetype: "application/epub+zip",
    "META-INF/container.xml": '<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container"><rootfiles><rootfile full-path="book.opf" media-type="application/oebps-package+xml"/></rootfiles></container>',
    "book.opf": '<package xmlns="http://www.idpf.org/2007/opf" version="2.0" unique-identifier="id"><metadata xmlns:dc="http://purl.org/dc/elements/1.1/"><dc:title>Review</dc:title><dc:identifier id="id">review</dc:identifier><dc:language>en</dc:language></metadata><manifest><item id="c" href="c.xhtml" media-type="application/xhtml+xml"/></manifest><spine><itemref idref="c"/></spine></package>',
    "c.xhtml": `<html xmlns="http://www.w3.org/1999/xhtml"><head><title>Review</title></head><body><p>${word}</p></body></html>`,
  };
  return makeZip(Object.entries(entries).map(([name, data]) => ({ name, data: Buffer.from(data), store: name === "mimetype" })));
}
async function nonPdf(type: "png" | "cbz" | "epub" | "djvu", action: "rename" | "replace") {
  const dir = join(root, `${type}-${action}`);
  settings(dir);
  const path = join(dir, `source.${type}`);
  const saved = join(dir, `saved.${type}`);
  const oldPng = makePng(40, 40, [255, 255, 255]);
  const newPng = makePng(40, 40, [0, 0, 0]);
  const cbz = (data: Buffer) => makeZip([{ name: "001.png", data }]);
  const original = type === "png" ? oldPng : type === "cbz" ? cbz(oldPng) : type === "epub" ? epub("ORIGINALWORD") : readFileSync("tests/issue-6312.djvu");
  const replacement = type === "png" ? newPng : type === "cbz" ? cbz(newPng) : epub("REPLACEDWORD");
  writeFileSync(path, original);
  await withControlledSumatra(EXE, async (client, proc) => {
    await client.waitForRenderIdle();
    const before = await query(client, ["clone-page", 1]);
    const textBefore = await query(client, ["cached-text", 1]);
    renameSync(path, join(dir, `moved.${type}`));
    if (action === "replace") writeFileSync(path, replacement);
    const clone = await query(client, ["clone-page", 1]);
    const cached = await query(client, ["cached-text", 1]);
    record({ kind: "non-pdf-before-save", type, action, before, textBefore, clone, cached });
    const saveRequest = client.request(ControlCommand.TestSaveFileAs, [saved]);
    const modal = await Promise.race([saveRequest.then(() => 0), waitForTopWindow(proc.pid!, "#32770", 5000)]);
    if (modal) postMessage(modal, WM_CLOSE, 0, 0);
    const save = await saveRequest;
    const bytes = existsSync(saved) ? readFileSync(saved) : null;
    const savedSource = !bytes ? "unavailable" : bytes.equals(original) ? "original" : bytes.equals(replacement) ? "replacement" : "other";
    record({ kind: "non-pdf-source", type, action, inputSha256: createHash("sha256").update(original).digest("hex"), before, textBefore, clone, cached, save, savedSource });
    check(before[0] === 0 && Number(/^ink=(-?\d+)/.exec(String(before[1]))?.[1] ?? -1) >= 0, `${type} invalid input: ${before}`);
    check((save[0] === 0) === Boolean(bytes), `${type} save status/bytes disagree`);
  }, ["-appdata", dir, "-log-to-file", join(dir, "app.log"), path]);
}
if (process.argv.includes("--forms")) {
  for (let round = 0; round < 2; round++) for (const engine of ["mupdf", "pdfium"]) for (const type of ["text", "choice"] as const) await form(type, engine, round);
}
if (process.argv.includes("--non-pdf")) {
  for (const type of ["png", "cbz", "epub", "djvu"] as const) for (const action of ["rename", "replace"] as const) {
    if (type === "djvu" && action === "replace") continue;
    const only = process.argv.find(arg => arg.startsWith("--case="))?.slice(7);
    if (only && only !== `${type}-${action}`) continue;
    await nonPdf(type, action);
  }
}

