import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { ControlCommand } from "../tests/control.ts";
import { assemblePdf, cmdId, SETTINGS_FILE } from "../tests/util.ts";
import { killAndWait, launchControlled, takeStderr } from "../tests/win-automation.ts";
import { enumChildWindows, getClassName, getControlText, isWindowEnabled, postMessage, sendCopyDataW, sendText, waitForTopWindow, WM_CLOSE, WM_COMMAND } from "../tests/winapi.ts";

const dir = resolve(`out/full-review-save-dialog-${process.env.REVIEW_RUN ?? "dbg3"}`);
mkdirSync(dir, { recursive: true });
const reload = process.argv.includes("--reload");
const result: Record<string, unknown> = { kind: reload ? "E34-reload-dialog" : "E34-clean-save-dialog", dir, phases: [] };
function record(phase: string, value: unknown) {
  (result.phases as unknown[]).push({ phase, value });
  writeFileSync(join(dir, "result.json"), JSON.stringify(result, null, 2));
  console.log(phase, JSON.stringify(value));
}
function pdf(word: string) {
  const stream = `BT /F1 24 Tf 72 700 Td (${word}) Tj ET`;
  return assemblePdf([
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Count 1 /Kids [3 0 R] >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
    `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`,
  ]);
}
const original = join(dir, "original.pdf"), other = join(dir, "other.pdf"), saved = join(dir, "saved.pdf");
writeFileSync(original, pdf("ORIGINALWORD"), "latin1");
writeFileSync(other, pdf("OTHERWORD"), "latin1");
writeFileSync(join(dir, SETTINGS_FILE), "UiLanguage = en\nUseTabs = true\nRestoreSession = false\nCheckForUpdates = false\nReloadModifiedDocuments = false\n");
const { proc, client, frame } = await launchControlled(["-appdata", dir, "-log-to-file", join(dir, "app.log"), original], { env: { SOLOKPDF_ENGINE: "pdfium" } });
let dialog = 0;
let forced = false;
try {
  await client.waitForRenderIdle();
  record("original", await client.request(ControlCommand.TestCurrentTab));
  if (reload) writeFileSync(original, readFileSync("out/full-review-followup-data/encrypted.pdf"));
  postMessage(frame, WM_COMMAND, cmdId(reload ? "CmdReloadDocument" : "CmdSaveAs"), 0);
  dialog = await waitForTopWindow(proc.pid!, "#32770", 5000);
  if (!dialog) throw new Error("no dialog");
  const edits: { hwnd: number; text: string }[] = [];
  const controlDeadline = Date.now() + 5000;
  do {
    edits.length = 0;
    enumChildWindows(dialog, hwnd => {
      if (getClassName(hwnd) === "Edit") edits.push({ hwnd, text: getControlText(hwnd) });
      return true;
    });
    if (reload || edits.some(e => e.text === "original" || e.text === "original.pdf")) break;
    await Bun.sleep(50);
  } while (Date.now() < controlDeadline);
  record("dialog", { dialog, ownerEnabled: isWindowEnabled(frame), edits });
  const filename = edits.find(e => e.text === "original" || e.text === "original.pdf");
  if (!reload && !filename) throw new Error("no filename edit");
  record("dde-open", String(sendCopyDataW(frame, 0x44646557, `[Open("${other}",0,0,0)]`)));
  const deadline = Date.now() + 5000;
  let current: unknown;
  do {
    current = await client.request(ControlCommand.TestCurrentTab);
    if (String(current).includes(other)) break;
    await Bun.sleep(50);
  } while (Date.now() < deadline);
  record("after-dde", current);
  if (!String(current).includes(other)) throw new Error("DDE did not activate other document");
  if (reload) {
    postMessage(dialog, WM_CLOSE, 0, 0);
    await Bun.sleep(300);
    record("after-reload-cancel", await client.request(ControlCommand.TestCurrentTab));
    record("after-reload-engine", await client.request(ControlCommand.TestCurrentPdf, ["cached-text", 1]));
  } else {
    sendText(filename!.hwnd, saved);
    postMessage(dialog, WM_COMMAND, 1, 0);
    const saveDeadline = Date.now() + 5000;
    while (!existsSync(saved) && Date.now() < saveDeadline) await Bun.sleep(50);
    const bytes = existsSync(saved) ? readFileSync(saved) : null;
    record("saved", { exists: Boolean(bytes), isOriginal: bytes?.equals(readFileSync(original)), isOther: bytes?.equals(readFileSync(other)) });
  }
} catch (error) {
  result.error = String(error);
  record("error", result.error);
} finally {
  if (dialog) postMessage(dialog, WM_CLOSE, 0, 0);
  if (proc.exitCode === null) {
    try { await client.quit(); } catch (error) { record("quit-error", String(error)); }
  }
  const exit = await Promise.race([proc.exited, Bun.sleep(5000).then(() => "timeout")]);
  if (exit === "timeout") { forced = true; await killAndWait(proc); }
  client.close();
  const stderr = await takeStderr(proc);
  writeFileSync(join(dir, "stderr.txt"), stderr);
  record("exit", { code: proc.exitCode, forced, stderr });
}
if (result.error) process.exitCode = 1;
